  "implementation": "def solve(case):
    # Validate required fields
    for key in ['passing', 'failing', 'required_difference', 'unresolved_difference']:
        if key not in case:
            raise ValueError(f"Missing key: {key}")
        if not isinstance(case[key], list):
            raise ValueError(f"{key} must be a list")

    passing = case['passing']
    failing = case['failing']
    required = set(case['required_difference'])
    unresolved = set(case['unresolved_difference'])

    # Compute ordered difference (changes in failing but not in passing)
    pass_set = set(passing)
    diff = [x for x in failing if x not in pass_set]

    # Verify required is a subset of diff
    if not required.issubset(diff):
        raise ValueError("required_difference is not a subset of the computed difference")

    tests_count = 0

    def test(subset):
        nonlocal tests_count
        tests_count += 1
        subset_set = set(subset)
        # unresolved -> test is UNRESOLVED, treated as not FAIL
        if subset_set & unresolved:
            return False
        return required.issubset(subset_set)

    # ddmin algorithm preserving order
    def ddmin(items):
        if len(items) == 0:
            test([])  # count the test of the empty set
            return [] if required.issubset(set()) else []
            # required.issubset(set()) is True iff required is empty, so empty is FAIL
        if len(items) == 1:
            return items if test(items) else []

        n = 2
        while True:
            m = len(items)
            # split into n contiguous subsets
            subsets = []
            for i in range(n):
                start = (i * m) // n
                end = ((i + 1) * m) // n
                subsets.append(items[start:end])

            reduced = False
            for subset in subsets:
                if test(subset):
                    items = subset
                    reduced = True
                    n = 2
                    break
            if reduced:
                continue

            # test complements
            for i in range(n):
                complement = items[:(i * m) // n] + items[((i + 1) * m) // n:]
                if test(complement):
                    items = complement
                    reduced = True
                    n = max(n - 1, 2)
                    break

            if not reduced:
                if n < len(items):
                    n = min(len(items), 2 * n)
                else:
                    return items

    isolated = ddmin(diff)
    return {
        "isolated_difference": isolated,
        "tests": tests_count
    }"
}
